// A record type is a shape — nothing declares it anywhere.
(int, String) parse(String raw) => (raw.length, raw.toUpperCase());

void main() {
  final r = parse('ada');
  print(r.$1);            // 3   — positional getters start at $1
  print(r.$2);            // ADA

  // Names in a positional record TYPE are documentation only.
  (int code, String body) res = (200, 'ok');
  print(res.$1);          // still $1 — there is no res.code

  // Named fields are read by name and never take a number.
  final mixed = (200, kind: 'json');
  print('${mixed.$1} ${mixed.kind}');   // no mixed.$2 exists

  // ❌ one positional field without a comma is just a parenthesised value
  final notARecord = (1);       // int
  final oneField = (1,);        // (int,)
  print(notARecord + 1);
  print(oneField.$1);

  // Shape drives assignability, field by field.
  (num, Object) widened = (1, 'a');     // ✅ (int, String) is a subtype
  // (String, int) swapped = (1, 'a');  // ❌ different shape
  print(widened);

  print(gap((0.0, 0.0), (3.0, 4.0)));   // 7.0
}

// A typedef names the shape without creating a class.
typedef Point = (double x, double y);

double gap(Point a, Point b) => (a.$1 - b.$1).abs() + (a.$2 - b.$2).abs();

// A record has no members of its own — behaviour comes from an extension.
extension on Point {
  Point get flipped => (this.$2, this.$1);
}

final positional = (1, 2);          // (int, int)
final named = (x: 1, y: 2);         // ({int x, int y})

void main() {
  print(positional == named);       // false — different shapes

  // Positional: bind by position.
  final (a, b) = positional;

  // Named: field name left of the colon, pattern to bind on the right.
  final (x: left, y: top) = named;

  // Shorthand: reuse the field's own name.
  final (:x, :y) = named;
  print('$a $b $left $top $x $y');

  // ❌ a named record has no positional fields to match
  // final (p, q) = named;

  // Named order is not part of the type; positional order is.
  ({int x, int y}) same = (y: 2, x: 1);   // ✅
  // (int, String) swapped = ('a', 1);    // ❌
  print(same == named);                   // true

  // Mixing: $1 for the positional part, the name for the rest.
  final resp = (200, body: 'ok');   // (int, {String body})
  print('${resp.$1} ${resp.body}');

  // Patterns bind the loop variable too.
  for (final (:x, :y) in [(x: 0, y: 0), (x: 3, y: 4)]) {
    print('$x,$y');
  }

  // …and a switch arm can match on the fields directly.
  print(switch (named) {
    (x: > 0, y: > 0) => 'quadrant I',
    (x: < 0, y: > 0) => 'quadrant II',
    _ => 'elsewhere',
  });
}

void main() {
  print((1, 'a') == (1, 'a'));           // true  — structural
  print((x: 1, y: 2) == (y: 2, x: 1));   // true  — named order is not shape
  print((1, 2) == (x: 1, y: 2));         // false — different shape

  // A compound cache key, for free.
  final cache = <(int userId, String locale), String>{};
  cache[(1, 'en')] = 'Hello';
  print(cache[(1, 'en')]);               // Hello — a different record instance

  // ❌ a field with identity equality poisons the whole record
  final k1 = ([1, 2], 'a');
  final k2 = ([1, 2], 'a');
  print(k1 == k2);                       // false — List == is identity
  final byList = <(List<int>, String), int>{k1: 1};
  print(byList[k2]);                     // null

  // ✅ put a value-comparable field in the tuple instead
  final byKey = <(String, String), int>{('1,2', 'a'): 1};
  print(byKey[('1,2', 'a')]);            // 1

  // ❌ a mutable field strands the entry it was inserted under
  final tag = Tag('draft');
  final notes = <(Tag, int), String>{(tag, 1): 'note'};
  tag.name = 'final';                    // hashCode changed
  print(notes[(tag, 1)]);                // null — still stored, unreachable
}

class Tag {
  Tag(this.name);
  String name;                           // mutable, and part of ==
  @override
  bool operator ==(Object other) => other is Tag && other.name == name;
  @override
  int get hashCode => name.hashCode;
}

// ❌ dynamic in, casts out — every caller re-guesses the shape
Map<String, dynamic> fetchOld() => {'code': 200, 'body': 'ok'};

void useOld() {
  final r = fetchOld();
  final code = r['code'] as int;   // a cast, and 'cod' would still compile
  print('$code ${r['body']}');     // body is dynamic from here on
}

// ✅ the shape lives in the signature; no casts, no dynamic
typedef Response = (int code, String body);

Response fetch() => (200, 'ok');

void use() {
  final (code, body) = fetch();    // destructure at the call site
  print('$code $body');
  // fetch().$3;                   // ❌ compile error, not a runtime null
}

// Value semantics come along for free.
const nothing = (0, '');
bool isEmpty(Response r) => r == nothing;

// A class earns its place as soon as there is an invariant or behaviour.
class HttpResponse {
  HttpResponse(this.code, this.body) : assert(code >= 100);
  factory HttpResponse.notFound() => HttpResponse(404, '');

  final int code;
  final String body;

  bool get isOk => code >= 200 && code < 300;
  HttpResponse copyWith({int? code}) => HttpResponse(code ?? this.code, body);
}
// A record cannot do any of those four things, and adding a third field
// to `Response` changes its type at every call site at once.

sealed class Job {}
class Queued extends Job {}
class Running extends Job { Running(this.pct); final int pct; }
class Done extends Job { Done(this.path); final String path; }

// Expression: arms are `pattern => value`, separated by commas.
String label(Job j) => switch (j) {
  Queued() => 'waiting',
  Running(:final pct) when pct > 90 => 'almost there',
  Running(:final pct) => '$pct%',
  Done(:final path) => 'saved to $path',
  // the catch-all here would be `_ =>`, never `default`
  // remove an arm: "the type 'Job' is not exhaustively matched"
};

// Statement: arms run code and produce nothing.
void handle(Job j) {
  switch (j) {
    case Queued():
    case Running():          // empty arm falls through to the next body
      log('in flight');
      // no `break` needed since Dart 3
    case Done(:final path):
      final file = open(path);   // statements and locals are fine here
      if (file == null) return;  // …so is an early return
      log('done');
  }
}

void render(Job j) {
  // ❌ a switch expression cannot start an expression statement
  // switch (j) { Queued() => log('q'), _ => log('x') };

  // ✅ use it where a value is expected
  final text = switch (j) { Queued() => 'q', _ => 'x' };
  log(text);
}

// Dart 3.7+: a local or a parameter named `_` binds nothing.

void demo(List<String> items, List<(int, String)> rows) {
  // ❌ used to work; now "Undefined name '_'"
  // final lengths = items.map((_) => _.length).toList();
  // ✅ name what you use
  final lengths = items.map((s) => s.length).toList();
  print(lengths);

  // Several wildcards in one signature no longer collide.
  final placeholder = (_, _) => 0;
  print(placeholder(1, 2));

  // Pattern wildcard: match a field and drop it.
  for (final (_, name) in rows) print(name);

  // A typed wildcard still tests the type and still binds nothing.
  Object payload = rows;
  if (payload case List<Object?> _) print('a list');

  try {
    risky();
  } catch (_) {          // the exception object is not bound
    print('failed');
  }

  var _ = expensive();   // discard a result without an unused-local warning
}

class Store {
  // Fields are NOT wildcards — this is an ordinary private field.
  int _ = 0;
  Store.from(this._);    // and `this._` still refers to it

  void bump() => _++;
  int get count => _;
}

// Only a single underscore is a wildcard; `__` binds exactly as before.
final legacy = (_, Object __) => __.toString();

void demo() {
  Object value = [1, 2, 3, 4];

  // Type test + `length >= 2`, then index from both ends.
  if (value case [final first, ...final rest, final last]) {
    print('$first $rest $last');      // 1 [2, 3] 4  — rest is a new list
  }

  // Unnamed rest: checks the length, allocates nothing.
  if (value case [final head, ..., final tail]) {
    print('$head…$tail');             // 1…4
  }

  // No rest element -> the length must match EXACTLY.
  if (value case [_, _]) print('never runs: length is 4');

  // A type argument moves the test to List<int>.
  if (value case <int>[final a, ...]) print(a + 1);   // 2
}

// ❌ a list pattern matches List, not any Iterable
void trap(Iterable<int> xs) {
  if (xs case [final first, ...]) {
    print(first);        // never runs for a Set or a where() result
  }

  // ✅ materialise it first
  final list = xs.toList();
  if (list case [final first, ...]) print(first);
}

// The named rest copies, so this is O(n) per call.
List<int> middle(List<int> xs) => switch (xs) {
  [_, ...final m, _] => m,
  _ => const [],
};

// In a hot path, take the ends without copying the middle.
(int, int)? ends(List<int> xs) =>
    xs case [final a, ..., final b] ? (a, b) : null;

final json = <String, Object?>{
  'type': 'user',
  'name': 'Ada',
  'age': 36,
  'meta': {'seen': true},
};

void demo() {
  // Two keys listed, four present — it matches. Subset, by design.
  if (json case {'type': 'user', 'name': final String name}) {
    print(name);                  // Ada
  }

  // A missing key just fails the match: no throw, nothing bound.
  if (json case {'email': final String email}) {
    print(email);
  } else {
    print('no email');            // `email` is not in scope here
  }

  // Size is never checked — this matches any map at all.
  if (json case {}) print('still a match');

  // Want "exactly these keys"? Say so in a guard.
  if (json case {'type': _, 'name': _} when json.length == 2) {
    print('exactly two keys');    // does not run: there are four
  }

  // Nesting works, and each subpattern carries its own type test.
  if (json case {'meta': {'seen': final bool seen}}) print(seen);
}

// ❌ keys must be constants — a variable key does not compile
void lookup(Map<String, Object?> m, String key) {
  // if (m case {key: final v}) print(v);   // not a constant expression
  final v = m[key];                         // ✅ an ordinary lookup
  if (v case final String s) print(s);
}

class Cart {
  Cart(this.items);
  final List<Item> items;

  // A getter — and the pattern below will call it.
  int get total => items.fold(0, (sum, i) => sum + i.price);
}

extension on Cart {
  bool get isEmpty => items.isEmpty;    // extension getters work in patterns
}

String describe(Cart c) => switch (c) {
  // `is Cart`, then c.total, then c.items — left to right, short-circuiting.
  Cart(total: > 10000, items: [_, _, ...]) => 'expensive basket',
  Cart(total: > 10000) => 'one expensive thing',
  Cart(isEmpty: true) => 'empty',
  _ => 'ordinary',
};

// ❌ no positional form: "Object patterns can only use named fields"
// String where(Point p) => switch (p) { Point(1, 2) => 'origin-ish', _ => '' };

// ✅ name the getter you want
String where(Point p) => switch (p) {
  Point(x: 1, y: 2) => 'at (1, 2)',
  Point(y: 0, x: final x) => 'on the x axis at $x',
  Point() => 'somewhere',             // no fields == a plain type test
};

// ❌ a throwing getter escapes the switch; the `_` arm never saves you
class Order {
  Money get total => throw StateError('not priced yet');
}
// switch (order) { case Order(total: final t): pay(t); case _: skip(); }

// ✅ model absence in the data, then let the pattern test it
class PricedOrder {
  Money? get total => _total;
  Money? _total;
}

String label(PricedOrder o) => switch (o) {
  PricedOrder(total: final Money t) => format(t),
  _ => 'not priced yet',
};

class Session { String? token; }

// ❌ two reads of a mutable field, plus `!` to shut the compiler up
void oldWay(Session s) {
  if (s.token != null && s.token!.length > 10) {
    send(s.token!);
  }
}

// ✅ one test, one binding, the condition in the guard
void newWay(Session s) {
  if (s.token case final String t when t.length > 10) {
    send(t);                 // a String local — no `!`, no second read
  } else {
    // `t` does not exist here: nothing matched
    print('no usable token');
  }
}

// Shape in the pattern, condition in the guard.
Widget row(Object json) {
  if (json case {'id': final int id, 'name': final String name}
      when name.isNotEmpty) {
    return Tile(id: id, title: name);
  }
  return const SizedBox.shrink();
}

// In a switch, a failed guard just moves on to the next case.
String bucket(int n) => switch (n) {
  int v when v > 100 => 'huge',
  int v when v > 10 => 'big $v',
  _ => 'small',
};

// ❌ guards do not count towards exhaustiveness
