//   Circle(:final r) when r > 1 => 'big circle',
//   Square() => 'square',
// };   // "The type 'Shape' isn't exhaustively matched ... 'Circle()'"

// ✅ one unguarded arm per case
String label(Shape s) => switch (s) {
  Circle(:final r) when r > 1 => 'big circle',
  Circle() => 'circle',
  Square() => 'square',
};

void demo(Map<String, int> scores, List<(String, int)> rows) {
  var a = 1, b = 2;
  (a, b) = (b, a);            // swap: the right side is evaluated first
  print('$a $b');             // 2 1

  (a, _) = (9, 0);            // `_` discards the second field

  // ❌ only locals and parameters can be targets
  // (this.x, this.y) = (y, x);                 // "Only local variables ..."
  // (rows[0], rows[1]) = (rows[1], rows[0]);   // does not even parse

  // ❌ an assignment pattern cannot declare
  // (a, final c) = (1, 2);

  // The loop variable is a pattern too.
  for (final (name, score) in rows) print('$name: $score');
  for (final MapEntry(:key, :value) in scores.entries) print('$key=$value');
}

void narrowing(List<Object> raw) {
  // ❌ a compile error, not a runtime cast:
  //   "The matched value of type 'Object?' isn't assignable to 'int'"
  // for (final (int id, String name) in raw) print('$id $name');

  // ✅ narrow the iterable, then destructure what is left
  for (final (id, name) in raw.whereType<(int, String)>()) {
    print('$id $name');
  }
}

// `.entries` allocates one MapEntry per step — avoid it in a per-frame loop.
int sumHot(Map<String, int> m) {
  var total = 0;
  for (final key in m.keys) total += m[key]!;
  return total;
}

const adult = 18;
const retirement = 65;

String bracket(int age) => switch (age) {
  < 0 => 'impossible',
  < adult => 'minor',
  >= adult && < retirement => 'working age',   // a range, chained with &&
  _ => 'retired',
};

void gate(int age, int minAge) {
  // ❌ "The relational pattern expression must be a constant"
  // if (age case > minAge) print('ok');

  // ✅ a runtime comparison belongs in the guard
  if (age case final a when a > minAge) print('ok $a');
}

// ❌ String defines == but not >, and the pattern calls the operator
// String cmp(String s) => switch (s) { > 'a' => 'gt', _ => 'other' };
// ✅ compare something that has the operator
String cmp(String s) => switch (s.compareTo('a')) { > 0 => 'gt', _ => 'other' };

// Constant branches bind nothing, so this is free.
bool isWeekend(String day) => switch (day) {
  'sat' || 'sun' => true,
  _ => false,
};

// ❌ "different type and/or finality in this branch of the logical-or pattern"
// String show(Object v) => switch (v) {
//   int n || double n => 'number $n',
//   _ => 'other',
// };
// ✅ one type both branches agree on
String show(Object v) => switch (v) {
  num n => 'number $n',
  _ => 'other',
};

// Same name, same type, different getters — perfectly legal.
String size(Shape s) => switch (s) {
  Circle(r: final v) || Square(side: final v) => 'size $v',
};

// The shared-body form obeys the same rule.
void handle(Object v) {
  switch (v) {
    case int _:
    case double _:            // both bind nothing
      print('numeric');
    case String s:
      print(s);
  }
}

const maxRetries = 3;
final int configuredLimit = readConfig();      // not const

int backoffMs(int attempt) => switch (attempt) {
  0 => 0,
  maxRetries => -1,             // constant pattern: attempt == maxRetries
  // configuredLimit => -1,     // ❌ "must be a valid constant"
  const (60 * 60) => 3600,      // a computed constant needs const(...)
  final n => n * 200,           // `final n` is how you BIND instead of compare
};

class Point {
  const Point(this.x, this.y);
  final int x, y;
}

void objectVersusConst() {
  final runtime = Point(1, 2);                 // built at run time
  print(switch (runtime) {
    const Point(1, 2) => 'constant pattern',   // == against the canonical const
    Point(x: 1, y: 2) => 'object pattern',     // type test + getter reads
    _ => 'neither',
  });                                          // prints "object pattern"

  const canonical = Point(1, 2);
  print(switch (canonical) {
    const Point(1, 2) => 'constant pattern',   // prints this one
    _ => 'neither',
  });
}

// ❌ object patterns have no positional form
// String at(Point p) => switch (p) { Point(1, 2) => 'origin-ish', _ => '' };

// ✅ shape goes in an object pattern, value in a constant pattern
String at(Point p) => switch (p) {
  Point(x: 0, y: 0) => 'origin',
  Point(y: 0) => 'on the x axis',
  _ => 'elsewhere',
};

// lib/src/payment.dart — every subtype lives in this one library
sealed class Payment {}
final class Card extends Payment { Card(this.last4); final String last4; }
final class Cash extends Payment {}
// v2 adds: final class Wallet extends Payment { Wallet(this.provider); ... }

// Adding Wallet turns this red here AND in every consumer package.
String receipt(Payment p) => switch (p) {
  Card(:final last4) => 'card ****$last4',
  Cash() => 'cash',
  // "The type 'Payment' isn't exhaustively matched ... 'Wallet()'"
};

// Nullable types include null in the space.
String maybe(Payment? p) => switch (p) {
  Card() => 'card',
  Cash() => 'cash',
  null => 'none',
};

// Statements with no default are checked too.
void log(Payment p) {
  switch (p) {
    case Card(): analytics.send('card');
    case Cash(): analytics.send('cash');
  }
}

// ❌ the catch-all that silences the compiler and ships the bug
String receiptLoose(Payment p) => switch (p) {
  Card(:final last4) => 'card ****$last4',
  _ => 'cash',                    // a Wallet payment now prints "cash"
};

// If third parties must be able to add cases, do not seal — dispatch.
abstract interface class Receiptable {
  String receiptLine();           // a new implementation brings its own
}

// The union half — no build_runner, no generated file.
sealed class Loaded<T> {}

final class Idle<T> extends Loaded<T> { const Idle(); }
final class Loading<T> extends Loaded<T> { const Loading(); }
final class Data<T> extends Loaded<T> {
  const Data(this.value);
  final T value;
}
final class Failed<T> extends Loaded<T> {
  const Failed(this.error, {this.retryIn});
  final Object error;
  final Duration? retryIn;
}

Widget build(Loaded<List<Post>> state) => switch (state) {
  Idle() || Loading() => const Spinner(),
  Data(value: []) => const EmptyView(),          // nested, no guard needed
  Data(:final value) => PostList(value),
  Failed(retryIn: final Duration d) => RetryIn(after: d),
  Failed(:final error) => ErrorView(error),
};

// The data half is what a generator still writes for you.
final class Draft {
  const Draft({required this.title, required this.body, this.tags = const []});

  final String title;
  final String body;
  final List<String> tags;

  Draft copyWith({String? title, String? body, List<String>? tags}) => Draft(
        title: title ?? this.title,
        body: body ?? this.body,
        tags: tags ?? this.tags,
      );

  @override
  bool operator ==(Object other) =>
      other is Draft &&
      other.title == title &&
      other.body == body &&
      listEquals(other.tags, tags);

  @override
  int get hashCode => Object.hash(title, body, Object.hashAll(tags));
}
