class _ChartState extends State<Chart> {
  var _extent = (0.0, 1.0);

  @override
  Widget build(BuildContext context) {
    // Two getter reads. Nothing is allocated by destructuring.
    final (min, max) = _extent;

    // This one is a constructor call. It escapes into the painter,
    // so the optimizer cannot sink it — it allocates every frame.
    final span = (min: min, max: max, range: max - min);
    return CustomPaint(painter: _Painter(span));
  }
}

// A const record is canonicalized: one instance for the whole program.
const emptyExtent = (0.0, 0.0);

// ❌ the NAMED rest copies the middle on every match
Widget summary(List<Item> items) => switch (items) {
  [final first, ...final middle, final last] =>
      Text('${first.name} +${middle.length} ${last.name}'),
  _ => const SizedBox.shrink(),
};

// ✅ the unnamed rest only checks the length
Widget summary2(List<Item> items) => switch (items) {
  [final first, ..., final last] =>
      Text('${first.name} +${items.length - 2} ${last.name}'),
  _ => const SizedBox.shrink(),
};

